      "title": "University of Birmingham — MA Philosophy of Religion and Ethics",
      "p1_hook": "The dialogue between classical theological metaphysics and contemporary analytic ethics represents one of the most fertile terrains in modern philosophy. Holding a 3.7/4.0 GPA in Islamic Studies alongside an Associate Degree in Politics, Philosophy, and Economics (PPE), I bring a distinctive comparative foundation. My grounding in Islamic scholastic theology (Kalam) and jurisprudence provides an intimate understanding of normative ethical systems, while my PPE training equips me with the analytic tools—normative ethics, political philosophy, and epistemology—to examine these systems in dialogue with contemporary thought.",
