      "title": "Oxford University — MSt in Hebrew and Jewish Studies",
      "p1_hook": "The intellectual history of the medieval Mediterranean was fundamentally an ecumenical enterprise, wherein Jewish, Islamic, and Christian thinkers shared a common philosophical vocabulary. Graduating with a 3.7/4.0 GPA in Islamic Studies alongside an Associate Degree in Politics, Philosophy, and Economics (PPE), I have specialized in classical Arabic scholastic theology and legal theory. Recognizing that thinkers like Moses Maimonides and Saadia Gaon composed their seminal philosophical treatises in Judeo-Arabic, I seek at Oxford to bridge Islamic scholasticism with medieval Jewish philosophy.",
